// The shapes ultraview reads and writes (docs/design.md §3, §4, §6):
//
//   model.json        agent-authored: app, systems, capabilities, edges, tour, glossary
//   flows/<id>.json   agent-authored: a cited walk through the map
//   lenses/<id>.json  agent-authored: one saved question and its cited answer
//   timeline.jsonl    appended: one entry per agent task / PR / manual note
//   changes/<id>.json generated by `diff --record`: one change set
//   view.json         generated: the merged view-model the viewer draws
//
// Type-only apart from the enum tables, so the viewer bundle can import it
// without pulling anything else in.

export const MODEL_SCHEMA = 1;
export const VIEW_SCHEMA = 1;

/** What a system is (model.json `systems[].kind`). */
export const SYSTEM_KINDS = ["ui", "service", "worker", "library", "data", "external", "infra", "script", "test", "config"] as const;
export type SystemKind = (typeof SYSTEM_KINDS)[number];

/** Who the viewer opens for by default (model.json `app.audience`). */
export const AUDIENCES = ["everyone", "developers"] as const;
export type Audience = (typeof AUDIENCES)[number];

/** Every node kind of the view-model; the id prefix of a node is its kind (`cap:checkout`). */
export const NODE_KINDS = ["cap", "sys", "mod", "file", "sym", "route", "screen", "entity", "job", "ext", "infra"] as const;
export type NodeKind = (typeof NODE_KINDS)[number];

/**
 * Every edge kind of the view-model. `rpc`: a call to a tRPC procedure or a Next
 * server action (`http` is a call to an HTTP route or host). `contains` is never
 * derived (the tree is `parent`); a model or lens edge may use it.
 */
export const EDGE_KINDS = ["import", "call", "http", "rpc", "data", "event", "queue", "extends", "config", "contains"] as const;
export type ViewEdgeKind = (typeof EDGE_KINDS)[number];

export const TIMELINE_SOURCES = ["agent", "pr", "manual"] as const;
export type TimelineSource = (typeof TIMELINE_SOURCES)[number];

export const CHANGE_KINDS = ["new", "changed", "removed"] as const;
export type ChangeKind = (typeof CHANGE_KINDS)[number];

// ---------------------------------------------------------------------------
// model.json

export interface ModelApp {
  name: string;
  /** Cited prose. */
  summary?: string;
  audience?: Audience;
}

export interface ModelSystem {
  /** Bare slug; the node id is `sys:<id>`. */
  id: string;
  label: string;
  kind: SystemKind;
  summary?: string;
  /** Globs over repo-relative paths; the most specific match wins a file. */
  paths: string[];
  exclude?: string[];
}

export interface ModelCapability {
  /** Bare slug; the node id is `cap:<id>`. */
  id: string;
  label: string;
  summary?: string;
  actors?: string[];
  /** Node ids (`mod:…`, `route:…`, `entity:…`, …). */
  members?: string[];
  /** Globs over repo-relative paths: matching files are members too. */
  paths?: string[];
  tags?: string[];
}

/** A relation the engine cannot see (queues, events, webhooks, cron, cross-repo). */
export interface ModelEdge {
  from: string;
  to: string;
  kind: ViewEdgeKind;
  label?: string;
  /** `path:line` the relation rests on. */
  cite?: string;
}

export interface TourStop {
  node: string;
  note: string;
}

export interface GlossaryEntry {
  term: string;
  meaning: string;
}

export interface Model {
  schema: typeof MODEL_SCHEMA;
  app: ModelApp;
  systems: ModelSystem[];
  capabilities: ModelCapability[];
  edges?: ModelEdge[];
  tour?: TourStop[];
  glossary?: GlossaryEntry[];
}

// ---------------------------------------------------------------------------
// flows/<id>.json and lenses/<id>.json

/** Repo-relative path → sha256 (hex) of the file's bytes when the flow / lens was saved. */
export type SourceHashes = Record<string, string>;

export interface FlowStep {
  node: string;
  note: string;
}

export interface Flow {
  schema: typeof MODEL_SCHEMA;
  id: string;
  title: string;
  trigger?: string;
  steps: FlowStep[];
  /** Stamped by `flow save`, never written by the model. */
  sources?: SourceHashes;
}

export interface LensEdge {
  from: string;
  to: string;
  kind?: ViewEdgeKind;
}

export interface Lens {
  schema: typeof MODEL_SCHEMA;
  id: string;
  question: string;
  /** Markdown; every sentence cites `[path:line]`. */
  answer: string;
  nodes: string[];
  edges?: LensEdge[];
  focus?: string;
  /** Stamped by `lens save`, never written by the model. */
  sources?: SourceHashes;
}

// ---------------------------------------------------------------------------
// conversations/<id>.json (docs/design.md §4): a thread of turns, each a lens
// answer to one question, committed like lenses.

export const CHAT_MODES = ["business", "dev"] as const;
export type ChatMode = (typeof CHAT_MODES)[number];
/** `agent`: answered by the user's coding agent; `facts`: written by ultraview from the facts alone. */
export const TURN_SOURCES = ["agent", "facts"] as const;
export type TurnSource = (typeof TURN_SOURCES)[number];

/**
 * What the question was asked about, when the user asked from the map: a node
 * id; an edge, `"<from-id> -> <to-id>"`; an insight id; a flow step,
 * `"<flow-id>:<n>"` (n from 1, like `#flow=<id>&step=<n>`).
 */
export interface ChatContext {
  node?: string;
  edge?: string;
  insight?: string;
  step?: string;
}

/** A turn's answer: the fields of a lens that answer (`answer` prose, every sentence cited; `nodes`; `edges`; `focus`). */
export interface TurnAnswer {
  answer: string;
  nodes: string[];
  edges?: LensEdge[];
  focus?: string;
}

export interface ChatTurn {
  question: string;
  /** BCP-47 tag of the question's language (`en`, `fr`, `ja`…). */
  lang: string;
  mode: ChatMode;
  context?: ChatContext;
  source: TurnSource;
  answer: TurnAnswer;
  /** Exactly 3 for an agent turn (in the question's language); at most 3 for a facts turn. */
  followUps: string[];
  /** Stamped when the turn is saved, like a lens's. */
  sources: SourceHashes;
  /** When the turn was saved (ISO-8601). */
  at: string;
  /** How long the answer took, in milliseconds. */
  ms?: number;
}

export interface Conversation {
  id: string;
  title: string;
  /** ISO-8601. */
  createdAt: string;
  turns: ChatTurn[];
}

// ---------------------------------------------------------------------------
// timeline.jsonl (one JSON object per line)

export interface TimelineItem {
  /** A node id. */
  ref: string;
  change: ChangeKind;
  note?: string;
}

export interface TimelineEntry {
  /** ISO-8601 time. */
  at: string;
  source: TimelineSource;
  title: string;
  /** What was asked (the user's request to the agent, the PR title, …). */
  request?: string;
  /** Cited prose: every sentence carries `[path:line]`, unless `auto`. */
  summary: string;
  items: TimelineItem[];
  /** Commit sha the change was measured against. */
  base?: string;
  /** Commit sha HEAD pointed at (uncommitted work sits on top of it). */
  head?: string;
  /** Id of the change set this entry records (`.ultraview/changes/<id>.json`); set by `diff --record`. */
  change?: string;
  /** True when `summary` was generated from the change counts rather than written: exempt from the citation rule. */
  auto?: boolean;
}

// ---------------------------------------------------------------------------
// changes/<id>.json (generated by `diff --record`, committed)

export const CHANGE_SCHEMA = 1;

/** How a node took part in a change: directly (added / changed / removed) or through the blast radius (impacted). */
export const CHANGE_STATUSES = ["added", "changed", "removed", "impacted"] as const;
export type ChangeStatus = (typeof CHANGE_STATUSES)[number];

/** What was diffed: committed + uncommitted work against a base branch, the staged changes, or the whole worktree against HEAD. */
export const DIFF_MODES = ["base", "staged", "worktree"] as const;
export type DiffMode = (typeof DIFF_MODES)[number];

/** Node kinds a change set classifies (externals and infra are never "changed"). */
export const CHANGE_NODE_KINDS = ["cap", "sys", "mod", "file", "sym", "route", "screen", "entity", "job"] as const;
export type ChangeNodeKind = (typeof CHANGE_NODE_KINDS)[number];

export const RISK_BUCKETS = ["high", "medium", "low"] as const;
export type RiskBucket = (typeof RISK_BUCKETS)[number];

export interface ChangeCounts {
  added: number;
  changed: number;
  removed: number;
  impacted: number;
}

export interface ChangedNode {
  /** A view node id; for `removed` it names a node no longer in the view. */
  id: string;
  kind: ChangeNodeKind;
  label: string;
  status: ChangeStatus;
  /** Structural parent (as in the view), kept so a removed node can still be placed. Absent for top-level nodes. */
  parent?: string;
  /** sym / route / screen / entity / job: where it is defined (`path:line`), in the base for a removed one. */
  at?: string;
  /** cap / sys / mod: directly changed (added, changed or removed) files at or under the node. */
  changedFiles?: number;
  /** cap / sys / mod: impacted files under the node. */
  impactedFiles?: number;
  /** file: lines added / deleted (git numstat; absent for binary and untracked files). */
  linesAdded?: number;
  linesDeleted?: number;
  /** file: changed line ranges of the new file, `[start, end]`, 1-based and inclusive. */
  hunks?: [number, number][];
  /** file: the path it was renamed from. */
  oldPath?: string;
  /** impacted file: hops to the nearest changed file along reverse dependency edges (1 = depends on it directly). */
  depth?: number;
}

/** The engine's per-module risk of one change (codeindex delta), keyed by view id. */
export interface ModuleRisk {
  /** `mod:<slug>`: the whole module (its slices share the score). */
  id: string;
  label: string;
  /** Module directory, repo-relative. */
  path: string;
  score: number;
  bucket: RiskBucket;
  /** Plain-words reasons behind the score, from the engine. */
  reasons: string[];
  /** Repo-relative paths of the module's changed files. */
  changedFiles: string[];
  changedSymbols: { total: number; exported: number };
  /** Blast radius: files depending on the change directly / within `depth` hops, and the other modules they sit in (`mod:` ids). */
  impact: { directFiles: number; transitiveFiles: number; modules: string[] };
  tests: { status: "covered" | "gap" | "n/a"; files: string[] };
}

/** An import that still points at a file the change removed (or renamed away). */
export interface BrokenImportRef {
  /** `file:<rel>` of the importer, still in the map. */
  from: string;
  /** The specifier as written in the importer. */
  spec: string;
  /** `file:<rel>` of the removed file it resolves to. */
  target: string;
  /** `file:<rel>` the target was renamed to, if it was. */
  renamedTo?: string;
  kind: "import" | "doc-link";
}

export interface ChangeSet {
  schema: typeof CHANGE_SCHEMA;
  /** `<YYYYMMDD-HHMMSS>-<short head sha>` (UTC) for committed work, `…-worktree` when uncommitted work is included. */
  id: string;
  /** ISO-8601 time it was recorded. */
  at: string;
  mode: DiffMode;
  /** What the change is measured against: the ref asked for and the commit it resolved to (merge-base for `base`). */
  base: { ref: string; sha: string };
  /** HEAD at record time; `dirty` when uncommitted (staged or worktree) changes are part of the set. */
  head: { sha?: string; dirty: boolean };
  /** Blast-radius depth (hops along reverse dependency edges). */
  depth: number;
  /** Nodes per kind and status. Every kind is present. */
  counts: Record<ChangeNodeKind, ChangeCounts>;
  /** Every classified node, sorted by id. */
  nodes: ChangedNode[];
  /** Per-module risk, highest score first. */
  risk: ModuleRisk[];
  broken: BrokenImportRef[];
  /** Changed paths outside the index (excluded, too big, not yet built): not mapped. */
  unindexed: string[];
  notes: string[];
  /** sha1 of what was diffed (mode, base, head, every changed path with its status and content hash): equal = the same change. */
  fingerprint: string;
}

// ---------------------------------------------------------------------------
// insights (generated, part of view.json)

export const INSIGHT_KINDS = ["hotspot", "hidden-coupling", "cycle", "dead-code", "untested-hub", "literal"] as const;
export type InsightKind = (typeof INSIGHT_KINDS)[number];

export const SEVERITIES = ["high", "medium", "low"] as const;
export type Severity = (typeof SEVERITIES)[number];

export interface Insight {
  /** `<kind>:<key>`, stable across runs (`cycle:src>src-routes>src-services`). */
  id: string;
  kind: InsightKind;
  severity: Severity;
  /** One line, plain words. */
  title: string;
  /** The evidence in plain words (counts, thresholds met). */
  detail: string;
  /** View node ids involved. */
  nodes: string[];
  /** `path:line` evidence. */
  cites: string[];
  /** A ready instruction for the user's agent. */
  prompt: string;
}

// ---------------------------------------------------------------------------
// view.json

export interface NodeMetrics {
  loc: number;
  pagerank: number;
  churn: number;
  tests: number;
}

export interface EntityFieldView {
  name: string;
  type: string;
  relation?: string;
}

/** A hyperlink a file holds: the registrable domain and the line. */
export interface NodeLink {
  host: string;
  line: number;
}

/** mod: the module a slice is part of, and the system it sits in (docs/design.md §2). */
export interface ModuleSlice {
  /** The whole module's id (`mod:src`), itself the slice in the system holding most of its files. */
  of: string;
  /** The system this slice's files sit in (`sys:database`). */
  system: string;
  /** What to show after the shared label to tell slices apart: `@ <system label>` (`@ Database`). */
  qualifier: string;
}

export interface ViewNode {
  id: string;
  kind: NodeKind;
  label: string;
  /**
   * Structural parent (sys ⊃ mod ⊃ file ⊃ sym/route/screen/job/entity). Absent for top-level nodes.
   * A file's system is the one its globs declare; its parent is the slice of its module in that system.
   */
  parent?: string;
  summary?: string;
  /** Citations found in `summary` (`path:line`). */
  cites: string[];
  /** Where a detected node is defined (`path:line`). */
  at?: string;
  metrics: NodeMetrics;
  /** Capabilities this node serves (claimed, inherited from a claimed ancestor, or aggregated from its children). */
  caps: string[];
  tags: string[];
  /** sys: the model's system kind. */
  role?: SystemKind;
  /** cap: who uses it. */
  actors?: string[];
  /** entity: its fields. */
  fields?: EntityFieldView[];
  /** file: hyperlinks to other sites (facts `links`), by line, at most LINKS_PER_FILE; the side panel lists them, the map never draws them. */
  links?: NodeLink[];
  /** infra: every file declaring this unit (environment overlays), when more than one does. */
  overlays?: string[];
  /**
   * mod: set on a minority slice (`mod:<slug>@<sys>`, tagged `slice`) — the
   * files of module `of` that sit in another system than the majority's.
   * Absent on `mod:<slug>` itself.
   */
  slice?: ModuleSlice;
}

export interface ViewEdge {
  from: string;
  to: string;
  kind: ViewEdgeKind;
  /** Underlying references: for a roll-up, the summed weight of the file-level edges it aggregates. */
  weight: number;
  /** True for everything ultraview detected or aggregated; false for model.json edges. */
  derived: boolean;
  label?: string;
  /** model.json edges: the `path:line` they rest on. */
  cite?: string;
}

export interface ViewCoverage {
  /** Share of code files that a (non-`_unassigned`) system holds. */
  filesInSystems: number;
  /** Share of non-test code modules that a model capability (not `_foundations`) claims. */
  modulesInCapabilities: number;
}

export interface ViewStale {
  /** Lens ids whose cited files changed since `lens save`. */
  lenses: string[];
  /** Flow ids whose cited files changed since `flow save`. */
  flows: string[];
  /** Module node ids whose ultraindex prose is stale. */
  prose: string[];
}

export interface ViewRepo {
  name: string;
  /** HEAD commit (short sha) the index was built at. */
  commit?: string;
  /** `origin` as an https URL, credentials stripped (`https://github.com/o/r`). */
  remote?: string;
  /** Absolute path of the repository on the machine that built the view: machine-local, for open-in-editor links. */
  root?: string;
}

export interface ViewModel {
  schema: typeof VIEW_SCHEMA;
  repo: ViewRepo;
  app: { name: string; summary?: string; cites: string[]; audience: Audience };
  nodes: ViewNode[];
  edges: ViewEdge[];
  flows: Flow[];
  lenses: Lens[];
  /** Every timeline entry, newest first. */
  timeline: TimelineEntry[];
  /** The latest recorded change set (`.ultraview/changes/`), or null. */
  changes: ChangeSet | null;
  /** Engine-grounded insights, most severe first. */
  insights: Insight[];
  glossary: GlossaryEntry[];
  tour: TourStop[];
  coverage: ViewCoverage;
  stale: ViewStale;
}
